components.css:
.ds-btn-primary {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  padding: 16px 20px;
  background: #D54A51;
  color: #ffffff;
  border: none;
  border-radius: 999px;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Arial, sans-serif;
  font-size: 16px;
  font-weight: 700;
  cursor: pointer;
  letter-spacing: 0.3px;
  transition: opacity 0.15s, transform 0.05s;
}
.ds-btn-primary:hover { background: #c84b53; }
.ds-btn-primary:focus-visible { outline: none; box-shadow: 0 0 0 3px rgba(213, 74, 81, 0.18); }
.ds-btn-primary:active:not(:disabled) { background: #B63A41; transform: scale(0.98); }
.ds-btn-primary:disabled { background: #d6d0cc; cursor: not-allowed; }

.ds-circle-btn {
  width: 54px;
  height: 54px;
  border-radius: 50%;
  border: none;
  background: rgba(255, 255, 255, 0.96);
  display: grid;
  place-items: center;
  box-shadow: 0 8px 22px rgba(33, 20, 8, 0.07);
  color: #141414;
  cursor: pointer;
  transition: opacity 0.15s, transform 0.1s;
}
.ds-circle-btn:active { transform: scale(0.95); opacity: 0.85; }

.ds-cart-btn {
  height: 58px;
  border-radius: 999px;
  border: none;
  background: #D54A51;
  color: #ffffff;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Arial, sans-serif;
  font-size: 13px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 0 16px;
  box-shadow: none;
  transition: opacity 0.15s;
}
.ds-cart-btn strong { font-size: 15px; font-weight: 800; }
.ds-cart-btn:active:not(:disabled) { transform: scale(0.98); }
.ds-cart-btn:disabled { opacity: 0.5; cursor: not-allowed; }

.ds-qty {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0;
  height: 58px;
  border: 1.5px solid #eadfd6;
  border-radius: 18px;
  background: #ffffff;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Arial, sans-serif;
  font-size: 19px;
}
.ds-qty button {
  width: 40px;
  height: 40px;
  border: none;
  background: transparent;
  color: #D54A51;
  cursor: pointer;
  font-size: 22px;
  font-weight: 600;
  display: grid;
  place-items: center;
  border-radius: 50%;
}
.ds-qty button:hover { background: #FDECEE; }
.ds-qty span {
  min-width: 30px;
  text-align: center;
  font-weight: 800;
  color: #161616;
}

.ds-chip {
  flex: 0 0 auto;
  min-width: max-content;
  height: 46px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 18px;
  border: 1px solid #eadfd6;
  border-radius: 999px;
  background: #ffffff;
  color: #171717;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Arial, sans-serif;
  font-size: 15px;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.2s, border-color 0.2s;
}
.ds-chip:hover, .ds-chip:focus-visible { background: #FDECEE; border-color: rgba(213, 74, 81, 0.18); color: #D54A51; outline: none; }

.ds-product-card {
  display: grid;
  grid-template-columns: 112px 1fr 42px;
  gap: 14px;
  align-items: center;
  padding: 12px;
  background: #ffffff;
  border: 1px solid #eadfd6;
  border-radius: 18px;
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s, transform 0.2s;
}
.ds-product-card img { width: 112px; height: 96px; object-fit: cover; border-radius: 14px; display: block; }
.ds-product-info { min-width: 0; }
.ds-product-info h3 { margin: 0 0 4px; font-family: 'Inter', sans-serif; font-size: 18px; font-weight: 800; line-height: 1.12; letter-spacing: -0.035em; color: #171717; }
.ds-product-info p { margin: 0; font-family: 'Inter', sans-serif; font-size: 14px; color: #6f6f76; line-height: 1.28; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.ds-product-price { margin-top: 6px; color: #D54A51; font-family: 'Inter', sans-serif; font-size: 17px; font-weight: 800; letter-spacing: -0.02em; }
.ds-product-add { width: 36px; height: 36px; border-radius: 50%; border: 1.5px solid #D54A51; color: #D54A51; display: grid; place-items: center; flex-shrink: 0; justify-self: end; background: #ffffff; font-size: 20px; }
.ds-product-card:hover, .ds-product-card:focus-visible { background: #FDECEE; border-color: rgba(213, 74, 81, 0.18); outline: none; }
.ds-product-card:active { transform: scale(0.985); }

.ds-metrics {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 0;
  background: #ffffff;
  border: 1px solid #eadfd6;
  border-radius: 18px;
  padding: 14px 8px;
  box-shadow: 0 8px 22px rgba(33, 20, 8, 0.07);
}
.ds-metric {
  display: flex;
  gap: 8px;
  align-items: center;
  justify-content: center;
  padding: 0 8px;
  border-right: 1px solid #eadfd6;
  min-width: 0;
}
.ds-metric:last-child { border-right: 0; }
.ds-metric strong { font-family: 'Inter', sans-serif; font-size: 15px; line-height: 1.15; white-space: nowrap; font-weight: 800; color: #161616; }
.ds-metric span { display: block; font-family: 'Inter', sans-serif; color: #8c8c91; font-size: 11px; line-height: 1.15; margin-top: 1px; }
.ds-metric--open strong { color: #119441; }

.ds-og-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }
.ds-og-btn {
  position: relative;
  min-height: 62px;
  border: 1px solid #eadfd6;
  border-radius: 10px;
  background: #ffffff;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  padding: 12px 10px 10px;
  cursor: pointer;
  transition: border-color 0.2s, background 0.2s, transform 0.2s;
  box-shadow: 0 6px 15px rgba(33,20,8,0.035);
  font-family: 'Inter', sans-serif;
}
.ds-og-btn strong { display: block; font-size: 12px; line-height: 1.15; font-weight: 700; color: #161616; }
.ds-og-btn small { display: block; margin-top: 3px; color: #7a7a80; font-size: 10px; line-height: 1.1; font-weight: 500; }
.ds-og-btn:hover { border-color: rgba(213, 74, 81, 0.18); background: #FDECEE; }
.ds-og-btn:active { transform: scale(0.98); }
.ds-og-btn--active { border-color: #D54A51; background: #FDECEE; box-shadow: 0 8px 18px rgba(213, 74, 81, 0.18); }
.ds-og-check { position: absolute; top: -8px; right: -8px; width: 22px; height: 22px; border-radius: 50%; background: #D54A51; color: #ffffff; display: grid; place-items: center; font-size: 12px; border: 2px solid #ffffff; box-shadow: 0 6px 14px rgba(213, 74, 81, 0.18); }
.ds-og-btn:not(.ds-og-btn--active) .ds-og-check { display: none; }

.ds-check-list { display: grid; }
.ds-check-row {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 0;
  border-bottom: 1px solid #eadfd6;
  font-family: 'Inter', sans-serif;
  font-size: 18px;
  cursor: pointer;
  transition: background 0.15s;
}
.ds-check-row:last-child { border-bottom: none; }
.ds-check-row:hover { background: rgba(253,236,238,0.3); }
.ds-check-name { display: flex; align-items: center; gap: 14px; color: #161616; }
.ds-check-box { width: 24px; height: 24px; border-radius: 7px; border: 2px solid #d6d0cc; display: grid; place-items: center; color: #ffffff; flex-shrink: 0; transition: background 0.15s, border-color 0.15s; font-size: 14px; }
.ds-check-box--checked { background: #D54A51; border-color: #D54A51; }
.ds-check-row > span:last-child { color: #D54A51; font-weight: 700; font-size: 15px; }

.ds-acai-chip {
  position: relative;
  min-height: 42px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border: 1px solid #eadfd6;
  border-radius: 12px;
  background: #ffffff;
  color: #222;
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  font-size: 14px;
}
.ds-acai-chip:hover { background: #FDECEE; border-color: rgba(213, 74, 81, 0.18); }
.ds-acai-chip--checked { border-color: #D54A51; background: #FDECEE; }
.ds-acai-box { width: 22px; height: 22px; border-radius: 6px; border: 1.6px solid #cfcfd3; display: grid; place-items: center; color: #ffffff; flex-shrink: 0; font-size: 13px; }
.ds-acai-chip--checked .ds-acai-box { background: #D54A51; border-color: #D54A51; }

.ds-floating-cart {
  position: sticky;
  bottom: 84px;
  display: grid;
  grid-template-columns: 76px 1fr 1px 104px;
  align-items: center;
  justify-items: center;
  height: 62px;
  padding: 0 12px;
  background: #D54A51;
  border: none;
  border-radius: 999px;
  color: #ffffff;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Arial, sans-serif;
  font-size: 15px;
  cursor: pointer;
  z-index: 25;
  box-shadow: 0 10px 26px rgba(213, 74, 81, 0.18);
}
.ds-floating-cart strong { font-size: 14px; font-weight: 800; }
.ds-floating-cart__bag { position: relative; display: grid; place-items: center; font-size: 30px; }
.ds-floating-cart__count { position: absolute; top: -5px; right: -8px; min-width: 18px; height: 18px; font-size: 11px; font-weight: 800; background: #ffffff; color: #D54A51; border-radius: 999px; display: grid; place-items: center; padding: 0 4px; }
.ds-floating-cart__rule { width: 1px; height: 28px; background: rgba(255, 255, 255, 0.35); }
.ds-floating-cart__price { font-weight: 800; font-size: 16px; letter-spacing: -0.02em; }

.ds-selectable-card {
  min-height: 180px;
  border: 1px solid #eadfd6;
  border-radius: 18px;
  background: #ffffff;
  position: relative;
  padding: 20px 14px;
  display: grid;
  place-items: center;
  box-shadow: 0 8px 22px rgba(33, 20, 8, 0.07);
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s;
  text-align: center;
}
.ds-selectable-card:hover { border-color: #d6d0cc; }
.ds-selectable-card--active { border-color: #D54A51; background: linear-gradient(180deg, #fff8f0, #ffffff); }
.ds-selectable-card__radio { position: absolute; top: 18px; left: 18px; width: 26px; height: 26px; border-radius: 50%; border: 2px solid #eadfd6; }
.ds-selectable-card--active .ds-selectable-card__radio { border-color: #D54A51; box-shadow: inset 0 0 0 5px #ffffff; background: #D54A51; }
.ds-selectable-card h3 { margin: 4px 0 6px; font-family: 'Inter', sans-serif; font-size: 21px; font-weight: 800; color: #171717; }
.ds-selectable-card p { margin: 0; font-family: 'Inter', sans-serif; font-size: 15px; color: #6f6f76; }

.ds-error-banner {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 14px 16px;
  background: #fef2f2;
  border: 1px solid #fecaca;
  border-radius: 14px;
}
.ds-error-banner svg { flex-shrink: 0; margin-top: 1px; }
.ds-error-banner strong { display: block; font-family: 'Inter', sans-serif; font-size: 14px; font-weight: 700; color: #171717; margin-bottom: 2px; }
.ds-error-banner p { margin: 0; font-family: 'Inter', sans-serif; font-size: 13px; color: #6f6f76; line-height: 1.4; }
.ds-error-banner__retry {
  margin-left: auto;
  align-self: center;
  flex-shrink: 0;
  padding: 8px 16px;
  background: #ffffff;
  border: 1px solid #eadfd6;
  border-radius: 999px;
  color: #D54A51;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Arial, sans-serif;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition: border-color 0.15s;
}
.ds-error-banner__retry:hover { border-color: #D54A51; }

.ds-flavor-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.ds-flavor-card {
  position: relative;
  min-height: 58px;
  border: 1px solid #eadfd6;
  border-radius: 13px;
  background: #ffffff;
  display: grid;
  grid-template-columns: 1fr;
  align-items: center;
  padding: 13px 14px;
  cursor: pointer;
  transition: border-color 0.2s, background 0.2s;
}
.ds-flavor-card:hover { border-color: #D54A51; background: #FDECEE; }
.ds-flavor-card--active { border-color: #D54A51; background: #FDECEE; }
.ds-flavor-info strong { display: block; font-family: 'Inter', sans-serif; color: #161616; font-size: 13px; line-height: 1.12; font-weight: 800; margin-bottom: 3px; }
.ds-flavor-info span { display: block; font-family: 'Inter', sans-serif; color: #161616; font-size: 12px; font-weight: 800; }
.ds-flavor-check { position: absolute; right: -7px; top: -7px; width: 24px; height: 24px; border-radius: 999px; background: #D54A51; color: #ffffff; display: grid; place-items: center; font-size: 13px; border: 3px solid #ffffff; }
.ds-flavor-card:not(.ds-flavor-card--active) .ds-flavor-check { display: none; }

.ds-search-box {
  height: 62px;
  border: 1px solid #eadfd6;
  border-radius: 999px;
  background: #ffffff;
  display: flex;
  align-items: center;
  padding: 0 18px;
  gap: 13px;
  flex: 1;
  box-shadow: 0 7px 20px rgba(0,0,0,0.03);
}
.ds-search-box input {
  border: none;
  outline: none;
  width: 100%;
  background: transparent;
  color: #171717;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Arial, sans-serif;
  font-size: 16px;
}
.ds-search-box input::placeholder { color: #6f6f76; opacity: 1; }

.ds-required {
  display: inline-flex;
  align-items: center;
  min-height: 22px;
  padding: 4px 9px;
  border-radius: 999px;
  background: #FDECEE;
  color: #D54A51;
  font-family: 'Inter', sans-serif;
  font-size: 11px;
  font-weight: 800;
  white-space: nowrap;
}
